import{c as e,Q as t,j as r,m as o}from"./chunks/framework.BXc4yaFE.js";const h=JSON.parse('{"title":"Adaptive Graph Pruning for Multi-Agent Communication","description":"","frontmatter":{"url":"https://arxiv.org/abs/2506.02951","title":"Adaptive Graph Pruning for Multi-Agent Communication","archived_date":"2026-07-26T00:00:00.000Z","arxiv_id":2506.02951,"authors":["Boyi Li","Zhonghan Zhao","Der-Horng Lee","Gaoang Wang"],"domains":["cs.CL","cs.MA"],"html":"https://arxiv.org/html/2506.02951v3","pdf_path":"pdfs/2506.02951.pdf","published_date":"2025-06-03T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2025-06-03-agp-adaptive-graph-pruning-multi-agent-communication-2506-02951.md","filePath":"research/papers/2025-06-03-agp-adaptive-graph-pruning-multi-agent-communication-2506-02951.md","lastUpdated":1785909234000}'),n={name:"research/papers/2025-06-03-agp-adaptive-graph-pruning-multi-agent-communication-2506-02951.md"};function i(l,a,s,g,p,u){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="adaptive-graph-pruning-for-multi-agent-communication" tabindex="-1">Adaptive Graph Pruning for Multi-Agent Communication <a class="header-anchor" href="#adaptive-graph-pruning-for-multi-agent-communication" aria-label="Permalink to &quot;Adaptive Graph Pruning for Multi-Agent Communication&quot;">​</a></h1><p><strong>Authors</strong>: Boyi Li, Zhonghan Zhao, Der-Horng Lee, Gaoang Wang <strong>Published</strong>: June 3, 2025（最新版 v3：2025-07-23） <strong>Source</strong>: <a href="https://arxiv.org/abs/2506.02951" target="_blank" rel="noreferrer">https://arxiv.org/abs/2506.02951</a> · <a href="https://arxiv.org/html/2506.02951v3" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2506.02951 <strong>Categories</strong>: cs.CL; cs.MA <strong>PDF</strong>: <a href="https://arxiv.org/abs/2506.02951" target="_blank" rel="noreferrer">research/papers/pdfs/2506.02951.pdf</a></p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>Large Language Model (LLM) based multi-agent systems have shown remarkable performance in various tasks, especially when enhanced through collaborative communication. However, current methods often rely on a fixed number of agents and static communication structures, limiting their ability to adapt to varying task complexities. In this paper, we propose Adaptive Graph Pruning (AGP), a novel task-adaptive multi-agent collaboration framework that jointly optimizes agent quantity (hard-pruning) and communication topology (soft-pruning).</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li><strong>雙階段訓練</strong>：Stage 1 從異質 agent pool 採樣多種通訊拓撲、任務微調後保留表現前 2 的圖，產生 460 組 (任務, 邊權重矩陣, 節點遮罩) 監督資料；Stage 2 訓練聯合軟硬剪枝網路</li><li>剪枝網路四模組：Sentence-BERT 節點編碼器、2 層 GCN 主幹、雙線性投影邊權重頭、2 層 MLP 節點遮罩頭</li><li>雙損失：軟剪枝（邊）MSE + 負邊稀疏化、硬剪枝（節點）BCE + 稀疏懲罰 + 相干項；<strong>Gumbel-Sigmoid</strong> 連續-離散橋接，溫度 1.0→0.1 退火（早期探索多圖、後期收斂離散決策）</li><li>Agent pool：15 角色完全圖 K₁₅（數學求解器、程式設計專家、批評家、醫生等跨領域角色）</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>gpt-4o-mini：6 個 benchmark 平均 <strong>91.04%</strong> vs G-Designer <strong>89.56%</strong>（+1.48%）；對比單 agent baseline 提升 <strong>2.58%–9.84%</strong>（MMLU 87.65%、GSM8K 95.01%、HumanEval 90.62%）</li><li>Token 經濟性：MMLU 較 GPTSwarm 減少 <strong>90%+</strong> token；GSM8K 較 G-Designer 減 12.7% token 同時準確度 +1.04%；HumanEval 減 22%</li><li>收斂快：MMLU 第 10 訓練步即達 88% 準確度超越 baseline，GSM8K 第 12 步收斂超越 G-Designer 全程</li><li>gpt-3.5-turbo 遷移：平均 81.94%（+0.29%），但 MMLU 反降（−1.29%）</li><li>消融：移除軟剪枝掉 4.16–4.99pp；移除硬剪枝時提示長度增加 22–30%</li><li>案例研究：54% 任務最優圖與人設計拓樸一致（「完全直覺」）、43% 為人設計子集（「部分直覺」）、3% 為「反直覺」（含看似無關但提升效能的 agent）</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>作者自陳：雙剪枝策略能否跨 LLM 家族/規模遷移未知（主要測 gpt-4o-mini / gpt-3.5-turbo，未涵蓋 Claude、Llama 等）</li><li>效率分析不足，缺乏細緻的推理延遲/成本量化（僅節點邊分析）</li><li>所有結果限於純文字任務，對多模態、時序擴展、具身 agent（視覺語言、工具使用、機器人）場景的有效性未驗證</li><li>未提供反直覺 agent 組合為何有效的解釋性分析，僅為經驗觀察</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li>「軟剪枝（邊）+ 硬剪枝（節點）聯合最佳化」與本庫已收錄的 <code>agentprune-2410-02506</code>（首次形式化 MAS 通訊冗餘）方向一致，AGP 提供可訓練、任務自適應的量化解法，可補強 <code>core.md §PROPOSE 委派</code>（原 <code>graph.md</code>） fan-out 降噪的方法論基礎。</li><li>「3% 反直覺 agent 組合提升效能」提醒 <code>core.md §PROPOSE 委派</code>（原 <code>graph.md §G1</code>）「畫邊前問下游需要上游哪個具體產出」不能只靠直覺判斷拓樸——偶有反直覺依賴確實帶來增益。⚠️ 案例比例僅 3%，不足以動搖「答不出具體欄位就沒有這條邊」的預設保守原則。</li><li>Token 節省 90%+ 的量級與 <code>output-compress</code> 分級壓縮目標同構，但 AGP 靠訓練達成、非 prompt 層規則，遷移需要訓練基礎設施，本 workspace 目前不具備。⚠️ 跨模型家族遷移性未知，直接套用需先驗證。</li></ul>',16)])])}const d=e(n,[["render",i]]);export{h as __pageData,d as default};
